<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\Gateway;

use Civi\Lughauth\Features\Document\Template\Domain\Template;

class TemplateCursor
{
  public const string CODE_ASC = 'code';
  public const string CODE_DESC = '-code';

  public function __construct(
    private int $limit,
    private ?string $sinceUid = null,
    private ?string $sinceCode = null,
    private ?array $order = null,
  ) {
  }
  public function next(Template $template, ?int $size): TemplateCursor
  {
    $next = clone $this;
    $next->sinceUid = $template->uid();
    $next->sinceCode = $template->getCode();
    $next->limit = $size ?? $this->limit;
    return $next;
  }
  public function limit(): int
  {
    return $this->limit;  }
  public function sinceUid(): ?string
  {
    return $this->sinceUid;
  }
  public function sinceCode(): ?string
  {
    return $this->sinceCode;
  }
  public function order(): ?array
  {
    return $this->order;
  }
}
